// sync_fifo: parameterizable synchronous FIFO, first-word fall-through.
// Implements interface_spec.md per microarchitecture.md.
`timescale 1ns/1ps
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                         clk,
    input  wire                         rst_n,
    input  wire                         wr_en,
    input  wire [WIDTH-1:0]             wr_data,
    output wire                         full,
    input  wire                         rd_en,
    output wire [WIDTH-1:0]             rd_data,
    output wire                         empty,
    output wire [$clog2(DEPTH+1)-1:0]   count
);

    // Widths and constants, sized to match the registers they meet.
    localparam integer PW      = $clog2(DEPTH);
    localparam integer CW      = $clog2(DEPTH + 1);
    localparam integer DEPTH_I = DEPTH;
    localparam integer LAST_I  = DEPTH - 1;
    localparam integer ONE_I   = 1;

    localparam [PW-1:0] LAST     = LAST_I[PW-1:0];
    localparam [PW-1:0] PTR_ONE  = ONE_I[PW-1:0];
    localparam [CW-1:0] FULL_CNT = DEPTH_I[CW-1:0];
    localparam [CW-1:0] CNT_ONE  = ONE_I[CW-1:0];

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [PW-1:0] wr_ptr;
    reg [PW-1:0] rd_ptr;
    reg [CW-1:0] count_q;

    // Flags are compares on a register: no input-to-flag paths.
    assign full  = (count_q == FULL_CNT);
    assign empty = (count_q == {CW{1'b0}});
    assign count = count_q;

    // Flags gate the requests: overflow and underflow policy.
    wire wr_acc = wr_en && !full;
    wire rd_acc = rd_en && !empty;

    // First-word fall-through read port.
    assign rd_data = mem[rd_ptr];

    // Storage write, only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

    // Pointers and occupancy, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {PW{1'b0}};
            rd_ptr  <= {PW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            if (wr_acc) begin
                wr_ptr <= (wr_ptr == LAST) ? {PW{1'b0}} : (wr_ptr + PTR_ONE);
            end
            if (rd_acc) begin
                rd_ptr <= (rd_ptr == LAST) ? {PW{1'b0}} : (rd_ptr + PTR_ONE);
            end
            case ({wr_acc, rd_acc})
                2'b10:   count_q <= count_q + CNT_ONE;
                2'b01:   count_q <= count_q - CNT_ONE;
                default: count_q <= count_q;
            endcase
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not yet proven: no job file submitted).
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
        assert (full  == (count_q == FULL_CNT));
        assert (empty == (count_q == {CW{1'b0}}));
        assert (!(full && empty));
        if (f_past_valid) begin
            assert (count_q <= FULL_CNT);
            assert (wr_ptr <= LAST);
            assert (rd_ptr <= LAST);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr == {PW{1'b0}});
                assert (rd_ptr == {PW{1'b0}});
            end else begin
                case ({$past(wr_acc), $past(rd_acc)})
                    2'b10:   assert (count_q == $past(count_q) + CNT_ONE);
                    2'b01:   assert (count_q == $past(count_q) - CNT_ONE);
                    default: assert (count_q == $past(count_q));
                endcase
                if ($past(wr_en && full))  assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_en && empty)) assert (rd_ptr == $past(rd_ptr));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
