// sync_fifo_tb: self-checking testbench for sync_fifo.
// Two FIFOs (DEPTH 8 x WIDTH 8, DEPTH 5 x WIDTH 12) on the same stimulus,
// each checked against a reference queue after every rising edge.
`timescale 1ns/1ps
`default_nettype none

module sync_fifo_tb;

    localparam integer DA  = 8;
    localparam integer WA  = 8;
    localparam integer DB  = 5;
    localparam integer WB  = 12;
    localparam integer CWA = $clog2(DA + 1);
    localparam integer CWB = $clog2(DB + 1);

    // Check identifiers.
    localparam integer C_COUNT      = 0;
    localparam integer C_FULL       = 1;
    localparam integer C_EMPTY      = 2;
    localparam integer C_EXCL       = 3;
    localparam integer C_DATA       = 4;
    localparam integer V_FULL       = 10;
    localparam integer V_WR_FULL    = 11;
    localparam integer V_DRAIN      = 12;
    localparam integer V_RD_EMPTY   = 13;
    localparam integer V_BOTH_EMPTY = 14;
    localparam integer V_BOTH_FULL  = 15;
    localparam integer V_BOTH_MID   = 16;
    localparam integer V_WR_WRAP    = 17;
    localparam integer V_RD_WRAP    = 18;
    localparam integer V_RST_BUSY   = 19;

    reg           clk;
    reg           rst_n;
    reg           wr_en;
    reg           rd_en;
    reg  [WB-1:0] wr_data;

    wire           full_a;
    wire           empty_a;
    wire [WA-1:0]  rd_data_a;
    wire [CWA-1:0] count_a;
    wire           full_b;
    wire           empty_b;
    wire [WB-1:0]  rd_data_b;
    wire [CWB-1:0] count_b;

    sync_fifo #(.DEPTH(DA), .WIDTH(WA)) dut_a (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data[WA-1:0]), .full(full_a),
        .rd_en(rd_en), .rd_data(rd_data_a), .empty(empty_a),
        .count(count_a)
    );

    sync_fifo #(.DEPTH(DB), .WIDTH(WB)) dut_b (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full_b),
        .rd_en(rd_en), .rd_data(rd_data_b), .empty(empty_b),
        .count(count_b)
    );

    always #5 clk = ~clk;

    // Reference model: index 0 is FIFO A, index 1 is FIFO B.
    reg [31:0] q [0:15];
    integer    head [0:1];
    integer    cnt  [0:1];
    reg [1:0]  wacc;
    reg [1:0]  racc;

    // Coverage counters.
    integer cov_full       [0:1];
    integer cov_wr_full    [0:1];
    integer cov_drain      [0:1];
    integer cov_rd_empty   [0:1];
    integer cov_both_empty [0:1];
    integer cov_both_full  [0:1];
    integer cov_both_mid   [0:1];
    integer cov_wr_wrap    [0:1];
    integer cov_rd_wrap    [0:1];
    integer cov_rst_busy   [0:1];

    integer cyc;
    integer passed;
    integer failed;

    function integer dep;
        input integer m;
        begin
            dep = (m == 0) ? DA : DB;
        end
    endfunction

    function [31:0] wdata_for;
        input integer m;
        begin
            if (m == 0) wdata_for = {{(32-WA){1'b0}}, wr_data[WA-1:0]};
            else        wdata_for = {{(32-WB){1'b0}}, wr_data};
        end
    endfunction

    function [31:0] got_count;
        input integer m;
        begin
            if (m == 0) got_count = {{(32-CWA){1'b0}}, count_a};
            else        got_count = {{(32-CWB){1'b0}}, count_b};
        end
    endfunction

    function [31:0] got_data;
        input integer m;
        begin
            if (m == 0) got_data = {{(32-WA){1'b0}}, rd_data_a};
            else        got_data = {{(32-WB){1'b0}}, rd_data_b};
        end
    endfunction

    function got_full;
        input integer m;
        begin
            got_full = (m == 0) ? full_a : full_b;
        end
    endfunction

    function got_empty;
        input integer m;
        begin
            got_empty = (m == 0) ? empty_a : empty_b;
        end
    endfunction

    task check;
        input integer m;
        input integer what;
        input         ok;
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                case (what)
                    C_COUNT:      $error("cycle %0d fifo %0d: count is %0d, expected %0d", cyc, m, got_count(m), cnt[m]);
                    C_FULL:       $error("cycle %0d fifo %0d: full is %b, expected count %0d of %0d", cyc, m, got_full(m), cnt[m], dep(m));
                    C_EMPTY:      $error("cycle %0d fifo %0d: empty is %b, expected count %0d", cyc, m, got_empty(m), cnt[m]);
                    C_EXCL:       $error("cycle %0d fifo %0d: full and empty both high", cyc, m);
                    C_DATA:       $error("cycle %0d fifo %0d: rd_data is %h, expected %h", cyc, m, got_data(m), q[m*8 + head[m]]);
                    V_FULL:       $error("fifo %0d: coverage: never filled to full", m);
                    V_WR_FULL:    $error("fifo %0d: coverage: no write while full", m);
                    V_DRAIN:      $error("fifo %0d: coverage: never drained to empty", m);
                    V_RD_EMPTY:   $error("fifo %0d: coverage: no read while empty", m);
                    V_BOTH_EMPTY: $error("fifo %0d: coverage: no write and read together when empty", m);
                    V_BOTH_FULL:  $error("fifo %0d: coverage: no write and read together when full", m);
                    V_BOTH_MID:   $error("fifo %0d: coverage: no write and read together in between", m);
                    V_WR_WRAP:    $error("fifo %0d: coverage: write pointer never wrapped", m);
                    V_RD_WRAP:    $error("fifo %0d: coverage: read pointer never wrapped", m);
                    V_RST_BUSY:   $error("fifo %0d: coverage: no reset while holding entries", m);
                    default:      $error("cycle %0d fifo %0d: check %0d failed", cyc, m, what);
                endcase
            end
        end
    endtask

    // One clock cycle: predict, take the edge, update the model, check.
    task step;
        integer m;
        integer d;
        integer widx;
        begin
            for (m = 0; m < 2; m = m + 1) begin
                d = dep(m);
                wacc[m] = rst_n && wr_en && (cnt[m] != d);
                racc[m] = rst_n && rd_en && (cnt[m] != 0);
                if (rst_n) begin
                    if (wr_en && (cnt[m] == d)) cov_wr_full[m]  = cov_wr_full[m] + 1;
                    if (rd_en && (cnt[m] == 0)) cov_rd_empty[m] = cov_rd_empty[m] + 1;
                    if (wr_en && rd_en) begin
                        if (cnt[m] == 0)      cov_both_empty[m] = cov_both_empty[m] + 1;
                        else if (cnt[m] == d) cov_both_full[m]  = cov_both_full[m] + 1;
                        else                  cov_both_mid[m]   = cov_both_mid[m] + 1;
                    end
                end else if (cnt[m] != 0) begin
                    cov_rst_busy[m] = cov_rst_busy[m] + 1;
                end
            end

            @(posedge clk);

            for (m = 0; m < 2; m = m + 1) begin
                d = dep(m);
                if (!rst_n) begin
                    head[m] = 0;
                    cnt[m]  = 0;
                end else begin
                    if (wacc[m]) begin
                        widx = (head[m] + cnt[m]) % d;
                        if (widx == d - 1) cov_wr_wrap[m] = cov_wr_wrap[m] + 1;
                        q[m*8 + widx] = wdata_for(m);
                    end
                    if (racc[m]) begin
                        if (head[m] == d - 1) cov_rd_wrap[m] = cov_rd_wrap[m] + 1;
                        head[m] = (head[m] + 1) % d;
                    end
                    if (wacc[m] && !racc[m]) cnt[m] = cnt[m] + 1;
                    if (racc[m] && !wacc[m]) begin
                        cnt[m] = cnt[m] - 1;
                        if (cnt[m] == 0) cov_drain[m] = cov_drain[m] + 1;
                    end
                    if (cnt[m] == d) cov_full[m] = cov_full[m] + 1;
                end
            end

            #1;
            cyc = cyc + 1;

            for (m = 0; m < 2; m = m + 1) begin
                d = dep(m);
                check(m, C_COUNT, got_count(m) == cnt[m]);
                check(m, C_FULL,  got_full(m)  == (cnt[m] == d));
                check(m, C_EMPTY, got_empty(m) == (cnt[m] == 0));
                check(m, C_EXCL,  !(got_full(m) && got_empty(m)));
                if (cnt[m] != 0) begin
                    check(m, C_DATA, got_data(m) == q[m*8 + head[m]]);
                end
            end
        end
    endtask

    integer        seed;
    integer        phase;
    integer        i;
    integer        wb;
    integer        rb;
    integer        mi;
    integer        k;
    integer        got_nonce;
    reg [31:0]     rnd;
    reg [8*64-1:0] nonce;

    initial begin
        clk     = 1'b0;
        rst_n   = 1'b0;
        wr_en   = 1'b0;
        rd_en   = 1'b0;
        wr_data = {WB{1'b0}};
        passed  = 0;
        failed  = 0;
        cyc     = 0;
        seed    = 32'h5EEDF1F0;
        for (mi = 0; mi < 2; mi = mi + 1) begin
            head[mi]           = 0;
            cnt[mi]            = 0;
            cov_full[mi]       = 0;
            cov_wr_full[mi]    = 0;
            cov_drain[mi]      = 0;
            cov_rd_empty[mi]   = 0;
            cov_both_empty[mi] = 0;
            cov_both_full[mi]  = 0;
            cov_both_mid[mi]   = 0;
            cov_wr_wrap[mi]    = 0;
            cov_rd_wrap[mi]    = 0;
            cov_rst_busy[mi]   = 0;
        end
        for (k = 0; k < 16; k = k + 1) q[k] = 32'd0;

        // 1. Reset with requests active: requests are ignored.
        wr_en   = 1'b1;
        rd_en   = 1'b1;
        wr_data = 12'hA5C;
        step;
        step;

        // 2. Read while empty.
        rst_n = 1'b1;
        wr_en = 1'b0;
        rd_en = 1'b1;
        step;
        step;

        // 3. Write and read together when empty: only the write is accepted.
        wr_en   = 1'b1;
        rd_en   = 1'b1;
        rnd     = $random(seed);
        wr_data = rnd[WB-1:0];
        step;

        // 4. Fill past full: writes while full are dropped.
        rd_en = 1'b0;
        for (i = 0; i < 10; i = i + 1) begin
            wr_en   = 1'b1;
            rnd     = $random(seed);
            wr_data = rnd[WB-1:0];
            step;
        end

        // 5. Write and read together when full, then in between.
        for (i = 0; i < 4; i = i + 1) begin
            wr_en   = 1'b1;
            rd_en   = 1'b1;
            rnd     = $random(seed);
            wr_data = rnd[WB-1:0];
            step;
        end

        // 6. Drain past empty.
        wr_en = 1'b0;
        for (i = 0; i < 12; i = i + 1) begin
            rd_en = 1'b1;
            step;
        end

        // 7. Random traffic in phases with different write/read biases.
        for (phase = 0; phase < 6; phase = phase + 1) begin
            case (phase)
                0:       begin wb = 80; rb = 30; end
                1:       begin wb = 30; rb = 80; end
                2:       begin wb = 50; rb = 50; end
                3:       begin wb = 95; rb = 95; end
                4:       begin wb = 70; rb = 40; end
                default: begin wb = 20; rb = 90; end
            endcase
            for (i = 0; i < 400; i = i + 1) begin
                rnd     = $random(seed);
                wr_en   = ((rnd % 100) < wb);
                rnd     = $random(seed);
                rd_en   = ((rnd % 100) < rb);
                rnd     = $random(seed);
                wr_data = rnd[WB-1:0];
                step;
            end
        end

        // 8. Reset during traffic.
        rd_en = 1'b0;
        for (i = 0; i < 6; i = i + 1) begin
            wr_en   = 1'b1;
            rnd     = $random(seed);
            wr_data = rnd[WB-1:0];
            step;
        end
        rst_n = 1'b0;
        wr_en = 1'b1;
        rd_en = 1'b1;
        step;
        rst_n = 1'b1;
        wr_en = 1'b0;
        rd_en = 1'b1;
        step;

        // 9. Balanced random traffic with a reset in the middle.
        for (i = 0; i < 300; i = i + 1) begin
            rst_n   = (i == 150) ? 1'b0 : 1'b1;
            rnd     = $random(seed);
            wr_en   = ((rnd % 100) < 60);
            rnd     = $random(seed);
            rd_en   = ((rnd % 100) < 50);
            rnd     = $random(seed);
            wr_data = rnd[WB-1:0];
            step;
        end
        rst_n = 1'b1;

        // 10. Final drain.
        wr_en = 1'b0;
        for (i = 0; i < 12; i = i + 1) begin
            rd_en = 1'b1;
            step;
        end
        rd_en = 1'b0;
        step;

        // Coverage: every corner case must have been reached.
        for (mi = 0; mi < 2; mi = mi + 1) begin
            check(mi, V_FULL,       cov_full[mi]       > 0);
            check(mi, V_WR_FULL,    cov_wr_full[mi]    > 0);
            check(mi, V_DRAIN,      cov_drain[mi]      > 0);
            check(mi, V_RD_EMPTY,   cov_rd_empty[mi]   > 0);
            check(mi, V_BOTH_EMPTY, cov_both_empty[mi] > 0);
            check(mi, V_BOTH_FULL,  cov_both_full[mi]  > 0);
            check(mi, V_BOTH_MID,   cov_both_mid[mi]   > 0);
            check(mi, V_WR_WRAP,    cov_wr_wrap[mi]    > 0);
            check(mi, V_RD_WRAP,    cov_rd_wrap[mi]    > 0);
            check(mi, V_RST_BUSY,   cov_rst_busy[mi]   > 0);
        end

        // Verdict, printed once just before $finish.
        nonce     = {(8*64){1'b0}};
        got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got_nonce == 0) nonce = {(8*64){1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
